 a,b,c,d=surface['corners']; start=[(a[0]+b[0])/2,(a[1]+b[1])/2,(a[2]+b[2])/2]; end=[(c[0]+d[0])/2,(c[1]+d[1])/2,(c[2]+d[2])/2]
 if previous is not None and math.hypot(start[0]-previous[0],start[2]-previous[2])>3.0: runs.append((current,currentSurfaces)); current=[]; currentSurfaces=[]
