 trialRuns.append({'id':i,'sourceWayId':'33976871','status':'experimental_estimate_only','widthMetres':4.0,'widthIsEstimated':True,'heightIsEstimated':True,'lengthMetres':round(st,3),'endMarginMetres':0.75,'points':out,'surfaces':surfaces})
